SELECT
COUNT(DISTINCT t1.id) as total
FROM
inspect_record t1
INNER JOIN inspect_record_item t2 on t1.id = t2.record_id

    t2.error_value_flag = 1
    and t2.item_tag in

        #{code}


        and t1.time >= #{param.period.begin}


        and t1.time <= #{param.period.end}

SELECT DISTINCT t1.id, t1.task_id, t1.task_name, t1.target_id, t1.target_name, t1.status, t1.result, t1.time, t1.user_id, t1.username, t1.nickname FROM inspect_record t1 INNER JOIN inspect_record_item t2 on t1.id = t2.record_id
t2.error_value_flag = 1 and t2.item_tag in
#{code}
and t1.time >= #{param.period.begin}
and t1.time <= #{param.period.end}
order by t1.time desc
